import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Яркость, экспозиция и контраст — три регулятора, которые есть в каждом фоторедакторе, и их легко перепутать. Все три делают фото светлее или темнее, но делают это по-разному.</p>\n<p>Неправильный выбор даёт худший результат. Фото, которому нужен контраст, будет выглядеть вымытым, если его только осветлить, а фото, которому нужна яркость, станет жёстким, если добавить только контраст.</p>\n<p>В этой статье мы объясним каждый регулятор, чем они отличаются, как взаимодействуют и к какому обращаться в каждой ситуации. Это основа для любой другой правки фото. На практике разницу между регуляторами покажет <a href=\"/ru/redaktor-yarkosti-izobrazheniya/\">Редактор яркости изображения</a> — попробуйте ползунок на своём фото и сравните до и после.</p>\n<h2 id=\"what-each-does\">Что делает каждый регулятор</h2>\n<p>Яркость сдвигает каждый пиксель к белому или к чёрному равномерно по всему снимку. Это самый простой регулятор, и он исправляет фото, тёмное или светлое в целом.</p>\n<p>Экспозиция меняет то, сколько света, как кажется, захватило изображение. Она по-разному влияет на света и тени, сохраняя больше деталей на краях, чем яркость.</p>\n<p>Контраст растягивает или сжимает расстояние между самой тёмной и самой светлой частями изображения. При повышении тёмное становится темнее, а светлое — светлее, а при понижении всё становится более похожим.</p>\n<p>Проще говоря, яркость двигает весь тональный диапазон, экспозиция меняет его форму, а контраст растягивает его. Каждый из них решает свою задачу.</p>\n<h2 id=\"brightness-explained\">Яркость простыми словами</h2>\n<p>Яркость — это равномерный сдвиг. Каждый пиксель становится светлее или темнее на одинаковую величину, поэтому относительные различия между объектами сохраняются.</p>\n<p>Это самая быстрая правка для фото, которое в целом слишком тёмное или слишком светлое. Тёмный снимок в помещении, осветлённый на 15 процентов, становится видимым, и изменение предсказуемо.</p>\n<p>Слабость яркости — в крайних точках. Если зайти слишком далеко, света вымываются, и яркие области превращаются в бесформенный белый цвет, потому что всё двигается вместе.</p>\n<p>Используйте яркость, когда всё фото нужно поднять или опустить. Это правильный инструмент для проблемы с общим уровнем и неправильный — для фото, тёмного только в одной части.</p>\n<p>На практике яркость — это регулятор, к которому возвращаются чаще всего. Даже опытные фотографы начинают правку с неё: один быстрый сдвиг показывает, есть ли в снимке вообще что спасать, и только потом подключаются остальные инструменты.</p>\n<h2 id=\"exposure-explained\">Экспозиция простыми словами</h2>\n<p>Экспозиция повторяет одноимённую настройку камеры. В камере экспозиция — это то, сколько света попадает на сенсор, а в редакторе она имитирует изменение этого количества.</p>\n<p>В отличие от яркости, экспозиция неравномерно обращается с тональным диапазоном. Она сильнее влияет на средние тона и мягче — на крайние света и тени, что сохраняет больше деталей.</p>\n<p>Поэтому экспозиция — лучший выбор, когда важны света. Яркое небо сохраняет форму при изменении экспозиции, а изменение яркости может его вымыть.</p>\n<p>Многие браузерные редакторы предлагают яркость, а не экспозицию, потому что её проще реализовать. Когда доступна только яркость, используйте небольшие шаги и внимательно проверяйте света после каждого.</p>\n<p>Если ваш редактор всё же предлагает экспозицию, проверьте её первой на пейзажах с небом. Разница с яркостью заметна сразу: облака сохраняют форму, а передний план светлеет, и снимок выглядит так, будто его сняли при лучшем свете.</p>\n<h2 id=\"contrast-explained\">Контраст простыми словами</h2>\n<p>Контраст — это разница. У высококонтрастного изображения глубокие чёрные и яркие белые цвета с сильным разрывом между ними, а у низкоконтрастного всё собрано в середине.</p>\n<p>Повышение контраста делает тёмное темнее, а светлое светлее. Оно добавляет плоскому фото энергии и глубины, но может и превратить тени в чёрный цвет, а света — в белый.</p>\n<p>Понижение контраста делает наоборот. Оно смягчает изображение, сближая тёмное и светлое, что подходит для фото в дымке и мягких портретов.</p>\n<p>Используйте контраст, когда фото выглядит плоским и серым, хотя его общая яркость правильная. Проблема не в уровне, а в разбросе.</p>\n<h2 id=\"how-they-interact\">Как три регулятора взаимодействуют</h2>\n<p>Яркость и контраст взаимодействуют напрямую. Осветление фото часто делает его плоским, потому что подъём теней уменьшает разрыв между тёмным и светлым, а добавление контраста его возвращает.</p>\n<p>Экспозиция и контраст тоже взаимодействуют. Увеличение экспозиции может вымыть света, а повышение контраста возвращает глубину, которую убрало изменение экспозиции.</p>\n<p>Обычная схема — сначала настроить яркость, затем контраст. Яркость задаёт общий уровень, а контраст уточняет разброс вокруг этого уровня.</p>\n<p>Изменение одного регулятора меняет то, что нужно другим. После большого сдвига яркости проверьте контраст ещё раз, а после большого сдвига контраста — снова проверьте яркость.</p>\n<h2 id=\"when-to-use-brightness\">Когда использовать яркость</h2>\n<p>Используйте яркость, когда всё фото слишком тёмное или слишком светлое. Тёмный снимок в помещении, тусклый пейзаж в пасмурную погоду или мутный скан — всем им нужен общий подъём.</p>\n<p>Яркость — также правильный выбор для скриншотов и документов. Текст должен читаться, а равномерный подъём делает тёмный скан чётким, не меняя его характера.</p>\n<p>Для фото, которое будет лежать за текстом, яркость — инструмент затемнения. Затемнённое изображение делает белый текст читаемым, что подходит для слайдов и плакатов.</p>\n<p>Избегайте яркости, когда неправильно только часть фото. Тёмный передний план при ярком небе нуждается в другом подходе, потому что яркость двигает обе части вместе.</p>\n<p>Для таких снимков помогает простая привычка при съёмке: коснитесь пальцем тёмной области на экране телефона, чтобы камера замеряла свет по ней. Передний план станет светлее, а небо, пусть и чуть ярче, обычно выдерживает такой сдвиг без потерь.</p>\n<h2 id=\"when-to-use-exposure\">Когда использовать экспозицию</h2>\n<p>Используйте экспозицию, когда важны света. Пейзаж с детальным небом, портрет с яркими бликами на коже или фото товара с блестящими поверхностями — всем им нужна более мягкая работа экспозиции.</p>\n<p>Экспозиция — лучший выбор для фото, которое лишь слегка не в порядке. Небольшое изменение экспозиции исправляет уровень без жёсткого вымывания, которое может вызвать большой сдвиг яркости.</p>\n<p>Когда редактор предлагает только яркость, имитируйте экспозицию небольшими шагами яркости и проверяйте света после каждого. Для большинства фото результат получается достаточно близким.</p>\n<p>Для фото, снятого при сильном солнечном свете, экспозиция — более безопасный регулятор. Она сохраняет яркие области, поднимая тени, чего яркость сделать не может.</p>\n<h2 id=\"when-to-use-contrast\">Когда использовать контраст</h2>\n<p>Используйте контраст, когда фото выглядит плоским и серым, хотя его общая яркость правильная. Проблема в разбросе, а не в уровне, и только контраст исправляет разброс.</p>\n<p>Контраст — правильный выбор для фото в дымке, туманных пейзажей и тусклых снимков в помещении. Небольшое повышение добавляет энергии и делает изображение снова плотным.</p>\n<p>Используйте отрицательный контраст, чтобы смягчить жёсткое фото. Портреты в полдень с сильными тенями выигрывают от более мягкого разброса, который сглаживает резкие края.</p>\n<p>Избегайте больших сдвигов контраста на фото с важными деталями в тенях или светах. Крайние точки страдают первыми, а выгоревшее небо или задавленную тень уже не вернуть.</p>\n<h2 id=\"order-of-edits\">Правильный порядок: сначала яркость, затем контраст</h2>\n<p>Начните с яркости, потому что она задаёт общий уровень. Слишком тёмное фото нужно поднять, прежде чем оценивать его контраст, а слишком яркое — сначала затемнить.</p>\n<p>Затем настройте контраст. Когда уровень задан, видно, плоское изображение или энергичное, и небольшое изменение контраста исправляет разброс.</p>\n<p>Наконец, проверьте яркость ещё раз. Изменение контраста может сделать изображение темнее или светлее на ощупь, поэтому небольшая поправка яркости после контраста часто улучшает результат.</p>\n<p>Работайте маленькими шагами на каждом этапе. Сдвиг яркости на 10 процентов, а затем сдвиг контраста на 10 процентов контролировать легче, чем один сдвиг на 30 процентов любого из регуляторов.</p>\n<p>Заведите себе правило «десять и десять»: сначала яркость плюс 10 процентов, затем контраст плюс 10 процентов, затем проверка. В большинстве случаев этого хватает, а если нет — повторите цикл, вместо того чтобы сразу крутить ползунки на максимум.</p>\n<h2 id=\"portraits\">Портреты: какой регулятор важнее всего</h2>\n<p>Портреты нуждаются в бережной яркости и аккуратном контрасте. Слишком тёмное лицо скрывает выражение, а лицо с избытком контраста выглядит жёстким и постаревшим.</p>\n<p>Начните с небольшого подъёма яркости на 10–15 процентов. Проверьте тона кожи: они должны выглядеть естественно освещёнными, а не так, будто вспышка сработала в упор.</p>\n<p>Добавляйте контраст только если портрет выглядит плоским. Небольшого повышения на 10 процентов обычно хватает, а большие сдвиги могут сделать кожу грубой.</p>\n<p>Для портрета на фоне яркого окна ни один регулятор не исправит и лицо, и фон одновременно. Осветлите бережно и примите компромисс или переснимите фото.</p>\n<h2 id=\"landscapes\">Пейзажи: баланс неба и переднего плана</h2>\n<p>Пейзажам часто нужна яркость для переднего плана и сдержанность для неба. Равномерное повышение яркости может вымыть облака, пока исправляет землю.</p>\n<p>Используйте умеренное повышение яркости и сначала проверяйте небо. Если облака теряют форму, значит, вы зашли слишком далеко, и правильный ответ — меньший сдвиг.</p>\n<p>Добавьте контраст, чтобы вернуть глубину, которую убрало осветление. Пейзаж с чистым небом и детальным передним планом нуждается в обоих регуляторах, работающих вместе.</p>\n<p>Утренние и вечерние пейзажи выигрывают от этой пары больше всего. Низкий свет даёт насыщенные цвета, а небольшой подъём яркости плюс небольшое повышение контраста выявляют детали.</p>\n<p>Золотой час — лучшее время для таких правок: свет уже мягкий, и регуляторам почти нечего исправлять. Если вы снимаете пейзажи регулярно, планируйте съёмку на час после рассвета или за час до заката.</p>\n<h2 id=\"screenshots\">Скриншоты и документы: сначала яркость</h2>\n<p>Скриншоты и отсканированные документы нуждаются в яркости больше, чем в контрасте. Цель — читаемый текст на чистом фоне, и равномерный подъём достигает этого напрямую.</p>\n<p>Повышайте яркость, пока текст не станет чётким, а фон — белым. Документ с чистым белым фоном и тёмным текстом легко читать и печатать.</p>\n<p>Добавляйте контраст только если текст после осветления всё ещё выглядит серым. Небольшое повышение затемняет буквы и обостряет края, что больше всего помогает мелкому тексту.</p>\n<p>Сохраняйте скриншоты в PNG. Формат без потерь сохраняет текст резким, что важнее размера файла, когда скриншот предназначен для чтения.</p>\n<h2 id=\"text-over-photos\">Текст поверх фото: главное — контраст</h2>\n<p>Текст на фото нуждается в контрасте между буквами и фоном за ними. Яркое фото с белым текстом не работает, а тёмное фото с чёрным текстом — точно так же.</p>\n<p>Затемните фото за текстом, чтобы белые буквы стали читаемыми. Снижение яркости на 20–30 процентов по всему изображению создаёт тёмную зону для текста.</p>\n<p>Как вариант, повысьте контраст фото, чтобы разделить светлые и тёмные области. Высококонтрастный фон даёт тексту более чёткую поверхность для размещения.</p>\n<p>Полное руководство по читаемому тексту читайте в статье <a href=\"/ru/blog/kontrast-i-chitaemost-teksta-na-foto/\">Контраст и читаемость: текст поверх фото</a>.</p>\n<h2 id=\"common-confusions\">Частые заблуждения о трёх регуляторах</h2>\n<p>Самое частое заблуждение — считать яркость и контраст одним и тем же. Это не так: яркость двигает уровень, а контраст меняет разброс, и фото может нуждаться в одном без другого.</p>\n<p>Ещё одно заблуждение — использовать яркость, чтобы исправить плоское фото. Плоское фото уже на правильном уровне, поэтому его осветление делает его только ярче и площе, а не лучше.</p>\n<p>Многие также используют контраст, чтобы исправить тёмное фото. Тёмное фото с высоким контрастом остаётся тёмным, просто с более глубокими тенями, а объект остаётся скрытым.</p>\n<p>Решение — сначала поставить диагноз, а потом редактировать. Спросите себя, слишком ли тёмное фото, слишком ли плоское или и то и другое, и выберите регулятор под диагноз.</p>\n<h2 id=\"testing-combinations\">Проверка сочетаний перед сохранением</h2>\n<p>Проверяйте яркость и контраст вместе, маленькими шагами. Подъём яркости на 10 процентов плюс повышение контраста на 10 процентов — хорошая отправная точка для тёмного плоского фото.</p>\n<p>Используйте вид сравнения после каждого изменения. Разделённый вид точно показывает, что сделала каждая настройка, поэтому можно остановиться, когда фото выглядит правильно.</p>\n<p>Проверяйте света и тени отдельно. Света выгорают первыми при яркости, а тени задавливаются первыми при контрасте, поэтому обе крайности нуждаются во внимании.</p>\n<p>Когда сочетание выглядит хуже оригинала, сбросьте и начните заново. Новая попытка с меньшими шагами обычно лучше, чем попытка спасти сильно отредактированное изображение.</p>\n<h2 id=\"cheat-sheet\">Быстрая шпаргалка по выбору регулятора</h2>\n<p>Используйте яркость, когда всё фото слишком тёмное или слишком светлое. Это самая быстрая правка для проблемы с общим уровнем, и она лучше всего подходит для скриншотов и документов.</p>\n<p>Используйте экспозицию, когда важны света и ваш редактор её предлагает. Она сохраняет детали в ярких областях лучше яркости, что подходит для пейзажей и портретов.</p>\n<p>Используйте контраст, когда фото выглядит плоским и серым, хотя его яркость правильная. Небольшое повышение добавляет энергии, а небольшое снижение смягчает жёсткое изображение.</p>\n<p>Используйте сначала яркость, затем контраст, когда фото нуждается в обоих. Порядок важен, потому что яркость задаёт уровень, а контраст уточняет разброс вокруг него.</p>\n<p>Распечатайте или сохраните эту шпаргалку рядом с рабочим местом: «тёмное — яркость, плоское — контраст, тёмное и плоское — сначала яркость, потом контраст». Через неделю она запомнится, и диагностика фото станет занимать секунды.</p>\n<h2 id=\"three-controls-for-thumbnails\">Яркость, экспозиция и контраст для миниатюр</h2>\n<p>Миниатюры видео показываются маленькими, поэтому им нужны сильные уровни и чёткий контраст. Тёмная плоская миниатюра теряется в ленте, а яркая и энергичная притягивает взгляд.</p>\n<p>Осветлите миниатюру чуть сильнее, чем полное фото. Маленький размер скрывает нюансы, поэтому чёткое, хорошо освещённое изображение работает лучше мрачного.</p>\n<p>Добавьте контраст, чтобы отделить объект от фона. Миниатюра с чётким объектом и различимым фоном читается мгновенно, даже в крошечном размере.</p>\n<p>Проверьте миниатюру в реальном размере перед публикацией. Уменьшите её на телефоне и проверьте, остаётся ли объект чётким, а текст, если он есть, — читаемым.</p>\n<p>Практические шаги смотрите в статьях <a href=\"/ru/blog/kak-nastroit-yarkost-izobrazheniya/\">Как настроить яркость изображения</a> и <a href=\"/ru/blog/kak-nastroit-kontrast-izobrazheniya/\">Как настроить контраст изображения</a>. Полные руководства читайте в статьях <a href=\"/ru/blog/redaktor-yarkosti-izobrazheniya-polnoe-rukovodstvo/\">Редактор яркости изображения: полное руководство</a> и <a href=\"/ru/blog/redaktor-kontrasta-izobrazheniya-polnoe-rukovodstvo/\">Редактор контраста изображения: полное руководство</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"В чём разница между яркостью и контрастом?","answer":"Яркость равномерно сдвигает каждый пиксель к белому или чёрному, двигая весь тональный диапазон вверх или вниз. Контраст растягивает или сжимает разрыв между самой тёмной и самой светлой частями. Тёмному фото нужна яркость, плоскому — контраст, а тёмному и плоскому — оба регулятора."},{"question":"Экспозиция — это то же самое, что яркость?","answer":"Нет, хотя они кажутся похожими. Экспозиция по-разному влияет на света и тени, сохраняя больше деталей на краях, а яркость двигает всё равномерно. Экспозиция мягче обращается с ярким небом, а яркость проще и быстрее для общей правки."},{"question":"Настраивать яркость или контраст первой?","answer":"Сначала яркость, затем контраст. Яркость задаёт общий уровень, а контраст уточняет разброс вокруг этого уровня. После изменения контраста проверьте яркость ещё раз, ведь изображение может казаться темнее или светлее, чем раньше."},{"question":"Почему фото выглядит плоским после осветления?","answer":"Осветление поднимает тени и уменьшает разрыв между тёмным и светлым, из-за чего изображение становится плоским. Добавьте небольшое повышение контраста после этого, чтобы вернуть глубину. Подъём яркости на 10 процентов плюс повышение контраста на 10 процентов — хорошее стартовое сочетание."},{"question":"Может ли контраст исправить слишком тёмное фото?","answer":"Нет. Контраст меняет разброс, а не уровень, поэтому тёмное фото с высоким контрастом остаётся тёмным, просто с более глубокими тенями. Сначала осветлите фото, чтобы исправить уровень, затем добавьте контраст, если оно выглядит плоским."},{"question":"Какой регулятор использовать для пейзажа в дымке?","answer":"Обычно контраст, часто с небольшим подъёмом яркости сначала. Дымка сглаживает тональный диапазон, поэтому повышение контраста возвращает глубину. Начните с 10 процентов яркости, если фото тёмное, затем добавьте 10–20 процентов контраста и проверьте небо."}];
